<?php use App\Models\PerfilClinico; require __DIR__.'/cabecera.php';$valores=$entrada??$perfil??[];$version=$entrada['version']??($perfil['version']??0); ?>
<section class="panel clinico-panel"><h2>Perfil clínico básico</h2>
<?php if(!$perfil): ?><p role="status" data-clinico-sin-perfil>Perfil aún no registrado. No se han confirmado grupo sanguíneo ni situación de alergias.</p><?php endif; ?>
<dl class="clinico-resumen"><dt>Grupo sanguíneo</dt><dd><?= e($perfil['grupo_sanguineo']??'No registrado') ?></dd><dt>Información de alergias</dt><dd><?= e(PerfilClinico::ESTADOS[$perfil['estado_alergias']??'no_registrado']) ?></dd></dl>
<?php if($perfil): ?><p class="field-hint">Creado por usuario #<?= (int)$perfil['creado_por_usuario_id'] ?> el <?= e($fechaClinica($perfil['creado_en'])) ?>. Última modificación por usuario #<?= (int)$perfil['actualizado_por_usuario_id'] ?> el <?= e($fechaClinica($perfil['actualizado_en'])) ?>. Versión <?= (int)$perfil['version'] ?>.</p><?php endif; ?>
<form method="post" action="<?= $baseClinica ?>/perfil-clinico" class="clinico-form" autocomplete="off" data-clinico-perfil>
<input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="version" value="<?= e((string)$version) ?>">
<div class="field-group"><label for="clinico-grupo">Grupo sanguíneo documentado</label><select id="clinico-grupo" name="grupo_sanguineo"><option value="">No registrado</option><?php foreach(PerfilClinico::GRUPOS as $grupo): ?><option value="<?= e($grupo) ?>" <?= ($valores['grupo_sanguineo']??'')===$grupo?'selected':'' ?>><?= e($grupo) ?></option><?php endforeach; ?></select><p class="field-hint">Registra solo un dato documentado. Si se desconoce, deja grupo y fuente vacíos.</p></div>
<div class="field-group"><label for="clinico-fuente">Referencia documental del grupo</label><input id="clinico-fuente" name="fuente_grupo_sanguineo" maxlength="120" value="<?= e($valores['fuente_grupo_sanguineo']??'') ?>"><p class="field-hint">Referencia breve revisada por ti; no se adjuntan archivos.</p></div>
<div class="field-group"><label for="clinico-observaciones">Observaciones generales breves (opcional)</label><textarea id="clinico-observaciones" name="observaciones" maxlength="500" rows="3"><?= e($valores['observaciones']??'') ?></textarea><p class="field-hint">Máximo 500 caracteres. No registrar diagnósticos, tratamientos ni antecedentes detallados.</p></div>
<div class="field-group"><label for="clinico-estado-alergias">Información sobre alergias</label><select id="clinico-estado-alergias" name="estado_alergias"><?php foreach(PerfilClinico::ESTADOS as $v=>$rotulo): ?><option value="<?= e($v) ?>" <?= ($valores['estado_alergias']??'no_registrado')===$v?'selected':'' ?>><?= e($rotulo) ?></option><?php endforeach; ?></select><p class="field-hint">«Sin conocidas» exige tu declaración expresa y ninguna entrada activa. Para registrar antecedentes, utiliza Alergias.</p></div>
<label class="clinico-confirmar"><input type="checkbox" name="confirmar" value="1" required>Confirmo la información que registraré, incluida cualquier declaración expresa de ausencia de alergias conocidas.</label>
<button class="button" type="submit">Guardar perfil clínico</button></form></section>
